tool_input.command:
export PATH="$(find "$HOME/.nvm/versions/node" -maxdepth 2 -name bin -type d 2>/dev/null | sort -V | tail -1):$PATH"; agent-browser --session review-issue-11 eval "
const studio = document.querySelector('mas-studio');
const sr = studio.shadowRoot;
if (sr) {
  const els = sr.querySelectorAll('*');
  return Array.from(els).slice(0,5).map(e => e.tagName).join(', ');
} else {
  return 'no shadow root, children: ' + Array.from(studio.children).slice(0,5).map(e => e.tagName).join(', ');
}" 2>&1
